-- ---------------------------------------------------------------------
-- supabase/seed/02_simulasi_denah_blok_A.sql
-- ---------------------------------------------------------------------
-- SIMULASI denah V1 (bukan denah lapangan final).
-- Blok A memakai grid 10 kolom x 15 baris agar A-001..A-149 dapat ditampilkan otomatis
-- berdasarkan nomor makam. Kapasitas tetap NULL (belum diketahui).
-- Semua nilai ini dapat diubah Admin melalui menu Denah Blok tanpa deploy ulang.
update public.blocks
set grid_columns = 10,
    grid_rows = 15
where code = 'A'
  and grid_columns is null
  and grid_rows is null;

-- ---------------------------------------------------------------------
-- Ringkasan hasil (harus: 149 makam, semua Blok A, A-001..A-149)
-- ---------------------------------------------------------------------
select
  count(*) as total_makam,
  count(*) filter (where b.code = 'A') as blok_a,
  min(g.grave_code) as kode_pertama,
  max(g.grave_code) as kode_terakhir,
  count(*) filter (where g.verification_status = 'NEEDS_VERIFICATION') as perlu_verifikasi,
  count(*) filter (where g.verification_status = 'VERIFIED') as terverifikasi
from public.graves g
left join public.blocks b on b.id = g.block_id;
